insert into public.live_test_items (block_id, item_number, source_day, source_stt, term_vi, term_en, prompt_vi, prompt_en, audio_text_vi, audio_text_en, cci_value, cci_measure, cci_unit_label, cci_source, cvr_value, cvr_measure, cvr_unit_label, cvr_breakdown, cpd_value, metadata)
select b.id, i.item_number, i.source_day, i.source_stt, i.term_vi, i.term_en, i.prompt_vi, i.prompt_en, i.audio_text_vi, i.audio_text_en, i.cci_value, i.cci_measure, i.cci_unit_label, i.cci_source, i.cvr_value, i.cvr_measure, i.cvr_unit_label, i.cvr_breakdown, i.cpd_value, i.metadata
from item_rows i
join resource r on true
join public.live_test_blocks b on b.resource_id = r.id and b.block_number = i.block_number
on conflict (block_id, item_number) do update set
  source_day = excluded.source_day,
  source_stt = excluded.source_stt,
  term_vi = excluded.term_vi,
  term_en = excluded.term_en,
  prompt_vi = excluded.prompt_vi,
  prompt_en = excluded.prompt_en,
  audio_text_vi = excluded.audio_text_vi,
  audio_text_en = excluded.audio_text_en,
  cci_value = excluded.cci_value,
  cci_measure = excluded.cci_measure,
  cci_unit_label = excluded.cci_unit_label,
  cci_source = excluded.cci_source,
  cvr_value = excluded.cvr_value,
  cvr_measure = excluded.cvr_measure,
  cvr_unit_label = excluded.cvr_unit_label,
  cvr_breakdown = excluded.cvr_breakdown,
  cpd_value = excluded.cpd_value,
  metadata = excluded.metadata;

commit;
